//? painted((g) => figures.draw(g, "kite", 480, 300, { size: 200, flip: true, turn: 0.4 })).colours > 4
//? (() => { const a = painted((g) => figures.draw(g, "bird", 300, 300, { size: 80, t: 0 })), b = painted((g) => figures.draw(g, "bird", 300, 300, { size: 80, t: 0.13 })); return a.sum !== b.sum; })()

//# weather: rain, snow, wind, fog, leaves and embers over the whole view
//  weather.rain(g,{n,wind,color,alpha}); weather.snow(g,{n,wind}); weather.wind(g,{strength:0..1,angle,color}) streaks along it; weather.fog(g,{amount,color}); weather.leaves(g,{n,wind,color}); weather.embers(g,{n,color}); weather.bubbles(g,{n}); weather.lightning(g,x,seed) ; all move by g.t and need nothing kept
//  needs: scene
const weather = { drops: (n, seed, f) => { for (let i = 0; i < n; i++) f(scene.chance(i, seed), scene.chance(i + 500, seed), scene.chance(i + 900, seed), i); }, loop: (v, n) => ((v % n) + n) % n,
  rain: (g, o = {}) => g.screen(() => weather.drops(o.n || 120, 11, (a, b, c) => { const w = o.wind || 0.2, y = weather.loop(b * H + g.t * (620 + 260 * c), H + 40) - 20, x = weather.loop(a * W + y * w + g.t * 60 * w, W + 40) - 20; g.line(x, y, x - 16 * w, y - 16, o.color || "#bcd7f2", 1.4, { alpha: (o.alpha || 0.45) * (0.5 + 0.5 * c) }); })),
  snow: (g, o = {}) => g.screen(() => weather.drops(o.n || 100, 12, (a, b, c, i) => { const y = weather.loop(b * H + g.t * (30 + 40 * c), H + 20) - 10, x = weather.loop(a * W + Math.sin(g.t * (0.6 + c) + i) * 18 + g.t * 50 * (o.wind || 0), W + 20) - 10; g.circle(x, y, 1.4 + 2.4 * c, "#ffffff", { alpha: 0.5 + 0.5 * c }); })),
  wind: (g, o = {}) => g.screen(() => { const s = o.strength == null ? 0.5 : Math.max(0, Math.min(1, o.strength)), q = o.angle || 0, dx = Math.cos(q), dy = Math.sin(q); weather.drops(Math.round(8 + 30 * s), 13, (a, b, c, i) => { const go = g.t * (160 + 420 * s) * (0.6 + 0.6 * c), x = weather.loop(a * W + go * dx, W + 200) - 100, y = weather.loop(b * H + go * dy + Math.sin(g.t * 1.4 + i) * 12, H + 60) - 30, l = 40 + 90 * s * c; g.line(x, y, x - dx * l, y - dy * l, o.color || "#ffffff", 1.4 + c, { alpha: (0.1 + 0.2 * s) * (0.4 + c * 0.6) }); }); }),
  fog: (g, o = {}) => g.screen(() => weather.drops(10, 14, (a, b, c, i) => g.glow(weather.loop(a * W + g.t * (6 + 14 * c), W + 500) - 250, H * (0.35 + 0.65 * b), 220 + 120 * c, o.color || "#c9d3de", (o.amount == null ? 0.5 : o.amount) * 0.32))),
  leaves: (g, o = {}) => g.screen(() => weather.drops(o.n || 22, 15, (a, b, c, i) => { const y = weather.loop(b * H + g.t * (34 + 30 * c), H + 30) - 15, x = weather.loop(a * W + g.t * 120 * (o.wind == null ? 0.4 : o.wind) + Math.sin(g.t * 1.6 + i) * 26, W + 30) - 15; g.ellipse(x, y, 7, 3.4, o.color || ["#e07a3f", "#d9a441", "#b5493c", "#7f9c4a"][i % 4], { turn: g.t * (1 + c * 2) + i, alpha: 0.9 }); })),
  embers: (g, o = {}) => g.screen(() => weather.drops(o.n || 40, 16, (a, b, c, i) => { const p = weather.loop(b + g.t * (0.06 + 0.1 * c), 1), x = a * W + Math.sin(g.t * 1.2 + i) * 24; g.circle(x, H - p * H, 1 + 2 * c, o.color || "#ff9d4d", { alpha: (1 - p) * 0.9, glow: 8 }); })),
  bubbles: (g, o = {}) => g.screen(() => weather.drops(o.n || 26, 17, (a, b, c, i) => { const p = weather.loop(b + g.t * (0.05 + 0.08 * c), 1); g.circle(a * W + Math.sin(g.t * 2 + i) * 10, H - p * (H + 20), 2 + 5 * c, "#dff6ff", { alpha: 0.18, stroke: "#dff6ff", width: 1 }); })),
  lightning: (g, x = W / 2, seed = 1) => g.screen(() => { let a = x, b = 0; for (let i = 0; i < 12; i++) { const na = a + (scene.chance(i, seed) - 0.5) * 70, nb = b + H / 13; g.line(a, b, na, nb, "#f2f6ff", 4 - i * 0.2, { glow: 22, glowColor: "#9fc2ff" }); a = na; b = nb; } }) };
//? ["rain","snow","wind","fog","leaves","embers","bubbles"].every((k) => painted((g) => weather[k](g, {})).bare < 1)
//? painted((g) => weather.wind(g, { strength: 1 })).sum !== painted((g) => weather.wind(g, { strength: 1 }), 2).sum

//# meters: bars, dials, lives and words on the picture
//  meters.bar(g,x,y,w,h,value 0..1,{color,back,label}); meters.dial(g,x,y,r,value 0..1,{color,label}); meters.pips(g,x,y,n,of,{figure:"heart",size}) lives; meters.label(g,words,x,y,{color,back,size}) on a plate; meters.arrow(g,x,y,angle,length,color); meters.timer(g,x,y,r,left 0..1,color)
//  meters.say(list,words,x,y,{color,size}) adds words that rise and fade; meters.step(list,dt) -> those left; meters.draw(list,g)
//  needs: scene, figures
const meters = { bar: (g, x, y, w, h, v, o = {}) => { v = Math.max(0, Math.min(1, Number(v) || 0)); g.rect(x, y, w, h, o.back || "rgba(10,12,18,0.55)", { r: h / 2 }); if (v > 0) g.rect(x + 2, y + 2, Math.max(h - 4, (w - 4) * v), h - 4, o.color || "#58d68d", { r: (h - 4) / 2 }); g.rect(x + 4, y + 3, Math.max(0, (w - 8) * v), Math.max(1, (h - 4) * 0.3), "#ffffff", { r: 3, alpha: 0.25 }); if (o.label) g.text(o.label, x + w / 2, y + h / 2, { size: Math.max(10, h * 0.62), align: "center", color: "#ffffff" }); },
  dial: (g, x, y, r, v, o = {}) => { v = Math.max(0, Math.min(1, Number(v) || 0)); const c = g.ctx; c.lineWidth = r * 0.22; c.lineCap = "round"; c.globalAlpha = 1; c.strokeStyle = "rgba(10,12,18,0.5)"; c.beginPath(); c.arc(x, y, r, Math.PI * 0.75, Math.PI * 2.25); c.stroke(); c.strokeStyle = o.color || "#4cc9f0"; c.beginPath(); c.arc(x, y, r, Math.PI * 0.75, Math.PI * (0.75 + 1.5 * v)); c.stroke(); if (o.label) g.text(o.label, x, y, { size: r * 0.55, align: "center" }); },
  pips: (g, x, y, n, of, o = {}) => { const s = o.size || 26; for (let i = 0; i < of; i++) figures.draw(g, o.figure || "heart", x + i * s * 1.15 + s / 2, y, { size: s, color: i < n ? o.color : "#5a5f6b", t: 0, alpha: i < n ? 1 : 0.5 }); },
  label: (g, words, x, y, o = {}) => { const s = o.size || 20, w = String(words).length * s * 0.58 + s * 1.2; g.rect(x - w / 2, y - s * 0.85, w, s * 1.7, o.back || "rgba(10,12,18,0.62)", { r: s * 0.6 }); g.text(words, x, y + 1, { size: s, color: o.color || "#ffffff", align: "center" }); },
  arrow: (g, x, y, a, l = 40, color = "#ffffff") => { const ex = x + Math.cos(a) * l, ey = y + Math.sin(a) * l; g.line(x, y, ex, ey, color, 5); g.poly([[ex + Math.cos(a) * 10, ey + Math.sin(a) * 10], [ex + Math.cos(a + 2.4) * 11, ey + Math.sin(a + 2.4) * 11], [ex + Math.cos(a - 2.4) * 11, ey + Math.sin(a - 2.4) * 11]], color); },
  timer: (g, x, y, r, left, color = "#ffd23f") => { g.circle(x, y, r, "rgba(10,12,18,0.55)"); if (left > 0) g.wedge(x, y, r - 3, -Math.PI / 2, -Math.PI / 2 + Math.PI * 2 * Math.min(1, left), color, { solid: true }); },
  say: (list, words, x, y, o = {}) => { list.push({ words: String(words), x, y, age: 0, color: o.color || "#ffffff", size: o.size || 24 }); return list; }, step: (list, dt) => list.filter((f) => { f.age += dt; f.y -= 46 * dt; return f.age < 1.1; }), draw: (list, g) => { for (const f of list) { g.text(f.words, f.x + 1.5, f.y + 1.5, { size: f.size, color: "#000000", align: "center", alpha: 0.4 * (1 - f.age / 1.1), weight: 800 }); g.text(f.words, f.x, f.y, { size: f.size, color: f.color, align: "center", alpha: 1 - f.age / 1.1, weight: 800 }); } } };
